//! Letter-trigram language models for autoswitch, built into the binary
//! from `assets/ngrams/<lang>.tsv` (generated by `tools/make_ngrams.py`).

use std::collections::HashMap;
use std::hint::black_box;
use std::sync::OnceLock;

use crate::selection::wipe_string;

const EN: &str = include_str!("../../../assets/ngrams/en.tsv");
const RU: &str = include_str!("../../../assets/ngrams/ru.tsv");
const UK: &str = include_str!("../../../assets/ngrams/uk.tsv");

/// Trigram counts of one language plus its normal word score.
#[derive(Debug)]
pub struct NgramModel {
    alphabet: &'static str,
    counts: HashMap<[char; 3], u32>,
    total: f64,
    /// Mean word score over the training text: subtracting it makes
    /// languages comparable.
    baseline: f64,
}

/// A text's score under a model.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Score {
    /// Mean trigram log-probability minus the language baseline: around 0
    /// for ordinary words, strongly negative for letter salad.
    pub normalized: f64,
    /// Letters of the language in the text.
    pub letters: usize,
}

impl NgramModel {
    /// Scores `text` the way `tools/make_ngrams.py` does: lower-cased, split
    /// into runs of the language's letters (outer apostrophes trimmed, runs
    /// under 2 letters skipped), each run padded as `^run$`, mean of
    /// ln((count + 0.5) / total) over all trigrams. `None` without such runs.
    /// The decoded copies of the text are wiped afterwards.
    pub fn score(&self, text: &str) -> Option<Score> {
        let folded: String = text
            .chars()
            .flat_map(char::to_lowercase)
            .map(fold)
            .collect();
        let mut sum = 0.0;
        let mut grams = 0usize;
        let mut letters = 0usize;
        let mut padded: Vec<char> = Vec::with_capacity(folded.len() + 2);
        for run in folded.split(|c: char| !self.alphabet.contains(c)) {
            let run = run.trim_matches('\'');
            let run_letters = run.chars().count();
            if run_letters < 2 {
                continue;
            }
            letters += run_letters;
            padded.clear();
            padded.push('^');
            padded.extend(run.chars());
            padded.push('$');
            for window in padded.windows(3) {
                let count = self
                    .counts
                    .get(&[window[0], window[1], window[2]])
                    .copied()
                    .unwrap_or(0);
                sum += ((f64::from(count) + 0.5) / self.total).ln();
                grams += 1;
            }
        }
        padded.fill('\0');
        black_box(&padded);
        wipe_string(folded);
        (grams > 0).then(|| Score {
            normalized: sum / grams as f64 - self.baseline,
            letters,
        })
    }

    fn parse(alphabet: &'static str, data: &str) -> Option<Self> {
        let mut counts = HashMap::new();
        let mut total = None;
        let mut baseline = None;
        for line in data.lines().filter(|l| !l.starts_with('#')) {
            let (key, value) = line.split_once('\t')?;
            match key {
                "total" => total = value.parse::<f64>().ok(),
                "baseline" => baseline = value.parse::<f64>().ok(),
                gram => {
                    let mut chars = gram.chars();
                    let trigram = [chars.next()?, chars.next()?, chars.next()?];
                    counts.insert(trigram, value.parse().ok()?);
                }
            }
        }
        Some(Self {
            alphabet,
            counts,
            total: total.filter(|t| *t > 0.0)?,
            baseline: baseline?,
        })
    }
}

/// The model for a language subtag (`en`, `ru`, `uk`), parsed on first use.
pub fn model_for(language: &str) -> Option<&'static NgramModel> {
    static MODELS: OnceLock<HashMap<&'static str, NgramModel>> = OnceLock::new();
    MODELS
        .get_or_init(|| {
            [
                ("en", "abcdefghijklmnopqrstuvwxyz'", EN),
                ("ru", "абвгдежзийклмнопрстуфхцчшщъыьэюя", RU),
                ("uk", "абвгґдеєжзиіїйклмнопрстуфхцчшщьюя'", UK),
            ]
            .into_iter()
            .filter_map(|(lang, alphabet, data)| Some((lang, NgramModel::parse(alphabet, data)?)))
            .collect()
        })
        .get(language)
}

/// Spelling variants the tables fold together.
fn fold(c: char) -> char {
    match c {
        'ё' => 'е',
        '’' | 'ʼ' => '\'',
        other => other,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn built_in_models_load() {
        for lang in ["en", "ru", "uk"] {
            assert!(model_for(lang).is_some(), "{lang}");
        }
        assert!(model_for("de").is_none());
    }

    #[test]
    fn real_words_beat_letter_salad() {
        let en = model_for("en").unwrap();
        let ru = model_for("ru").unwrap();
        assert!(en.score("hello").unwrap().normalized > en.score("ghbdtn").unwrap().normalized);
        assert!(ru.score("привет").unwrap().normalized > ru.score("руддщ").unwrap().normalized);
    }

    #[test]
    fn case_punctuation_and_yo_are_folded() {
        let ru = model_for("ru").unwrap();
        assert_eq!(ru.score("Ёлка").unwrap(), ru.score("елка").unwrap());
        let en = model_for("en").unwrap();
        assert_eq!(en.score("ab,cd").unwrap().letters, 4);
        assert_eq!(en.score("123 ,."), None);
        assert_eq!(
            en.score("i.e."),
            None,
            "1-letter runs are skipped, as in the script"
        );
    }
}
